import unittest

from solution import assign_windows


class AssignWindowsTests(unittest.TestCase):
    def test_consecutive_windows_include_every_item_once(self):
        self.assertEqual(
            assign_windows([0, 1, 2, 3, 4, 5, 6], 3),
            [[0, 1, 2], [3, 4, 5], [6]],
        )

    def test_exact_multiple_and_width_one(self):
        self.assertEqual(assign_windows([1, 2, 3, 4], 2), [[1, 2], [3, 4]])
        self.assertEqual(assign_windows([1, 2, 3], 1), [[1], [2], [3]])

    def test_width_larger_than_input_and_empty_input(self):
        self.assertEqual(assign_windows([1, 2], 5), [[1, 2]])
        self.assertEqual(assign_windows([], 4), [])

    def test_windows_are_independent_deep_copies(self):
        items = [{"values": [1]}, {"values": [2]}, {"values": [3]}]
        result = assign_windows(items, 2)

        items[0]["values"].append(10)
        self.assertEqual(result[0][0], {"values": [1]})

        result[0][0]["values"].append(20)
        result[0].append("extra")
        self.assertEqual(items[0], {"values": [1, 10]})
        self.assertEqual(result[1], [{"values": [3]}])

    def test_does_not_mutate_input(self):
        items = [1, 2, 3, 4]
        assign_windows(items, 2)
        self.assertEqual(items, [1, 2, 3, 4])

    def test_invalid_items_type(self):
        for items in (None, (), {}, "items"):
            with self.subTest(items=items), self.assertRaises(TypeError):
                assign_windows(items, 2)

    def test_invalid_width_type(self):
        for width in (True, False, 2.0, "2", None):
            with self.subTest(width=width), self.assertRaises(TypeError):
                assign_windows([], width)

    def test_nonpositive_width(self):
        for width in (0, -1, -10):
            with self.subTest(width=width), self.assertRaises(ValueError):
                assign_windows([1], width)


if __name__ == "__main__":
    unittest.main()

